(()=>{'use strict';const $=id=>document.getElementById(id),date=s=>new Date(s+'T00:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});let items=[],mode='all',busy=false,page=1;const rail=!!$('railItems'),parent=$(rail?'railItems':'newsFeed'),status=$(rail?'railStatus':'feedStatus'),refreshButton=$(rail?'railRefresh':'refreshFeed');
function valid(item){try{const u=new URL(item.url);return ['https://gov.near.org','https://near.org','https://www.near.org','https://github.com','https://x.com','https://nearblocks.io','https://defillama.com','https://nearhackathon.com','https://near.ai'].includes(u.origin)&&['proposals','news','github','onchain','data'].includes(item.kind)&&Array.isArray(item.affects)&&item.affects.length&&['title','summary','effect','next','date','checkedAt','status'].every(k=>typeof item[k]==='string'&&item[k].length)}catch{return false}}
function simulation(item){return item.simulation==='hsp029'?'./research.html?catalyst=hsp029#offset':item.simulation==='intents-fees'?'./research.html?catalyst=intents-fees#revenue':null}
function detail(item){$('catalystTitle').textContent=item.title;$('catalystSummary').textContent=item.summary;$('catalystEffect').textContent=item.effect;$('catalystNext').textContent=item.next;$('catalystSource').href=item.url;const sim=simulation(item);$('catalystSimulate').hidden=!sim;if(sim)$('catalystSimulate').href=sim;renderProjects(item);$('catalystDetail').showModal()}
const trackNames={defi:'Unstoppable DeFi',thesis:'Investment Thesis',privacy:'Privacy & Private AI',business:'Autonomous Business',swarms:'AI Swarms',security:'AI Security & Defense',agents:'Agent Economy',money:'Real-World Money',games:'Games With Real Economies',nfts:'NFTs That Do Something',memecoins:'Memecoins With Mechanics',social:'Social Money',open:'Open Innovation'};
function renderProjects(item){document.getElementById('eventProjects')?.remove();if(item.id!=='near-hackathon-2026')return;const box=document.createElement('section');box.id='eventProjects';const title=document.createElement('h3');title.textContent='Explore submitted projects';const select=document.createElement('select');select.setAttribute('aria-label','Filter projects by track');for(const [v,t]of [['','All tracks'],...Object.entries(trackNames)]){const o=document.createElement('option');o.value=v;o.textContent=t;select.append(o)}const list=document.createElement('div'),prev=document.createElement('button'),next=document.createElement('button'),nav=document.createElement('div');nav.className='project-pager';prev.textContent='Previous';next.textContent='Next';let n=1,run=0;async function update(){const request=++run;list.textContent='Loading projects…';try{const r=await fetch('/api/hackathon/projects?page='+n+'&track='+encodeURIComponent(select.value));if(!r.ok)throw Error();const d=await r.json();if(request!==run)return;list.replaceChildren();for(const p of d.projects){const row=document.createElement('p'),a=document.createElement('a');a.textContent=p.project_name;a.href=p.demo_url||'https://nearhackathon.com/#projects';a.target='_blank';a.rel='noopener noreferrer';row.append(a);const small=document.createElement('small');small.textContent=(p.tracks||[]).map(t=>trackNames[t]||t).join(' · ');row.append(small);list.append(row)}if(!d.projects.length)list.textContent='No projects listed in this track.';prev.disabled=n===1;next.disabled=n*d.pageSize>=d.total}catch{list.textContent='Directory unavailable. Open the original source below.'}}select.onchange=()=>{n=1;update()};prev.onclick=()=>{n--;update()};next.onclick=()=>{n++;update()};nav.append(prev,next);box.append(title,select,list,nav);$('catalystSource').parentElement.before(box);update()}
function render(){const railLink=rail?document.querySelector('.catalyst-rail .rail-all'):null;parent.replaceChildren();const selected=items.filter(i=>mode==='all'||i.kind===mode).sort((a,b)=>b.date.localeCompare(a.date));const size=10,pages=Math.max(1,Math.ceil(selected.length/size));page=Math.min(page,pages);for(const item of selected.slice((page-1)*size,page*size)){const button=document.createElement('button');button.type='button';button.className=rail?'rail-item':'economic-item';const title=document.createElement('span');title.className='economic-title';title.textContent=item.title;button.append(title);button.dataset.kind=item.kind;button.onclick=()=>detail(item);parent.append(button)}if(!selected.length){const empty=document.createElement('p');empty.className='quiet';empty.textContent='No reviewed catalysts in this category.';parent.append(empty)}let pager=$(rail?'railPages':'feedPages');if(!pager){pager=document.createElement('nav');pager.id=rail?'railPages':'feedPages';pager.className='catalyst-pages';pager.setAttribute('aria-label','Catalyst pages');parent.after(pager)}pager.replaceChildren();if(pages>1){for(let n=Math.max(1,page-2);n<=Math.min(pages,page+2);n++){const b=document.createElement('button');b.textContent=n;b.type='button';b.setAttribute('aria-label','Page '+n);if(n===page)b.setAttribute('aria-current','page');b.onclick=()=>{page=n;render()};pager.append(b)}}if(railLink)pager.append(railLink)}
async function refresh(){if(busy)return;busy=true;refreshButton.disabled=true;try{const r=await fetch('/api/catalysts',{cache:'no-store'});if(!r.ok)throw Error();const d=await r.json();items=(d.items||[]).filter(valid);render();status.textContent=''}catch{status.textContent='Catalyst update unavailable';if(!items.length)render()}finally{busy=false;refreshButton.disabled=false}}
refreshButton.onclick=refresh;document.querySelectorAll('[data-feed]').forEach(b=>b.onclick=()=>{mode=b.dataset.feed;page=1;document.querySelectorAll('[data-feed]').forEach(x=>{const on=x===b;x.classList.toggle('on',on);x.setAttribute('aria-pressed',String(on))});render()});$('closeCatalyst').onclick=()=>$('catalystDetail').close();$('catalystDetail').onclick=e=>{if(e.target===$('catalystDetail'))$('catalystDetail').close()};refresh();setInterval(()=>{if(!document.hidden)refresh()},60000);})();
